"const fs = require('fs');
const readline = require('readline');

const logPath = 'C:\\Users\\FORYOUCOM\\.gemini\\antigravity-ide\\brain\\fa5f2b96-9c7f-4245-b7c6-72c405a822ad\\.system_generated\\logs\\transcript.jsonl';

async function processLineByLine() {
  const fileStream = fs.createReadStream(logPath);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  let writes = [];

  for await (const line of rl) {
    try {
      const entry = JSON.parse(line);
      if (entry.tool_calls) {
        for (const call of entry.tool_calls) {
          if (call.name === 'write_to_file' || call.name === 'replace_file_content' || call.name === 'multi_replace_file_content') {
            const args = call.args || {};
            const target = args.TargetFile || '';
            if (target.toLowerCase().includes('franchisepageclient')) {
              writes.push({
                step: entry.step_index,
                type: call.name,
                args: args,
                timestamp: entry.created_at
              });
            }
          }
        }
      }
    } catch (e) {}
  }

  console.log("Found " + writes.length + " edits to FranchisePageClient.tsx");
  if (writes.length > 0) {
      for(let w of writes) {
          console.log(`Step ${w.step} [${w.timestamp}] - ${w.type}`);
          // write the args to a file for review
          const outPath = `d:\\anti-gv\\25. 120pie(new)_2\\scratch\\franchise_step_${w.step}.json`;
          fs.writeFileSync(outPath, JSON.stringify(w.args, null, 2));
          console.log(`Saved to ${outPath}`);
      }
  }
}

processLineByLine();
